package com.projecteden.ranking.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.projecteden.common.exception.ResourceNotFoundException;import com.projecteden.friend.domain.*;import com.projecteden.friend.repository.FriendRepository;import com.projecteden.ranking.domain.Ranking;import com.projecteden.ranking.dto.RankingResponseDTO;import com.projecteden.ranking.repository.RankingRepository;import com.projecteden.user.domain.User;import com.projecteden.user.repository.UserRepository;
@Service public class RankingService{private final RankingRepository rankings;private final FriendRepository friends;private final UserRepository users;public RankingService(RankingRepository rankings,FriendRepository friends,UserRepository users){this.rankings=rankings;this.friends=friends;this.users=users;}@Transactional public List<RankingResponseDTO> getFriendRanking(Long userId){User me=users.findById(userId).orElseThrow(()->new ResourceNotFoundException("사용자를 찾을 수 없습니다."));List<User> members=new ArrayList<>();members.add(me);friends.findByRequesterOrReceiverAndStatus(me,me,FriendStatus.ACCEPTED).forEach(f->members.add(f.getRequester().getId().equals(me.getId())?f.getReceiver():f.getRequester()));return members.stream().map(u->rankings.findByUser(u).orElseGet(()->rankings.save(Ranking.create(u)))).sorted(Comparator.comparingInt(Ranking::getConsecutiveLogins).reversed().thenComparing(Comparator.comparingInt(Ranking::getTotalPlayDays).reversed()).thenComparing(Comparator.comparingInt(Ranking::getSeasonAchievements).reversed())).map(r->new RankingResponseDTO(r.getUserId(),r.getUser().getNickname(),r.getConsecutiveLogins(),r.getTotalPlayDays(),r.getSeasonAchievements())).toList();}}
